#!/usr/bin/env bash
# build.sh — compose dist/ from core/. Single source of truth: core/*.md
#
#   ./build.sh           rebuild dist/
#   ./build.sh --check   verify dist/ is in sync (CI; exits 1 on drift)
#   ./build.sh --stats   show size/token estimates per generated file
#
# Requires: bash only. No network, no dependencies.

set -euo pipefail

ROOT=$(cd "$(dirname "$0")" && pwd)
CORE=$ROOT/core
VERSION=$(tr -d '[:space:]' < "$ROOT/VERSION")
REPO="https://github.com/GabxSup/lazyeng"

usage() {
    sed -n '2,9p' "$0" | sed 's/^# \{0,1\}//'
}

MODE=build
for arg in "$@"; do
    case $arg in
        --check)   MODE=check ;;
        --stats)   MODE=stats ;;
        -h|--help) usage; exit 0 ;;
        *) echo "build.sh: unknown argument: $arg" >&2; exit 2 ;;
    esac
done

BANNER="<!-- Generated by build.sh from core/*.md (lazyeng v$VERSION). Do not edit. -->"

if [ "$MODE" = check ]; then
    OUT=$(mktemp -d)/dist
else
    OUT=$ROOT/dist
    rm -rf "$OUT"
fi
mkdir -p "$OUT/cursor" "$OUT/windsurf" "$OUT/cline" "$OUT/skills/lazyeng"

# emit <outfile> <title> <note> <part>...
# Concatenates core/<part>.md with a generated banner, optional H1 and note.
emit() {
    out=$1; title=$2; note=$3; shift 3
    {
        printf '%s\n' "$BANNER"
        if [ -n "$title" ]; then printf '\n# %s\n' "$title"; fi
        if [ -n "$note" ]; then printf '\n%s\n' "$note"; fi
        for part in "$@"; do
            printf '\n'
            cat "$CORE/$part.md"
        done
    } > "$out"
}

# emit_yaml <outfile> <frontmatter-block> <title> <note> <part>...
# YAML frontmatter must be the first bytes of the file, so the banner follows it.
emit_yaml() {
    out=$1; fm=$2; title=$3; note=$4; shift 4
    {
        printf '%s\n' "$fm"
        printf '%s\n' "$BANNER"
        printf '\n# %s\n' "$title"
        if [ -n "$note" ]; then printf '\n%s\n' "$note"; fi
        for part in "$@"; do
            printf '\n'
            cat "$CORE/$part.md"
        done
    } > "$out"
}

# ── Chat surfaces: no tools, so no agent section ──────────────────────────────
emit "$OUT/system-prompt.md" "" \
    "Drop this whole file into the system prompt / custom instructions of any chat model. Full version." \
    base expanded

emit "$OUT/system-prompt-compact.md" "" \
    "Drop this whole file into the \`system\` field of any API call. Cheapest tier." \
    base

# ── Always-on instruction files: compact on purpose, every request pays for these
emit "$OUT/AGENTS.md" "LazyEng" \
    "Universal agent instructions ([agents.md](https://agents.md)). Also read by Cursor, Codex, Copilot, Gemini CLI, Zed, Amp, opencode, Jules, and others. Install: \`./install.sh --target agents\`" \
    base agent

emit "$OUT/CLAUDE.md" "LazyEng" \
    "Claude Code project instructions. Install: \`./install.sh --target claude\`" \
    base agent

emit "$OUT/GEMINI.md" "LazyEng" \
    "Gemini CLI context file. Install: \`./install.sh --target gemini\`" \
    base agent

emit "$OUT/copilot-instructions.md" "LazyEng" \
    "GitHub Copilot repository instructions. Install: \`./install.sh --target copilot\`" \
    base agent

emit "$OUT/CONVENTIONS.md" "LazyEng" \
    "Aider conventions file. Install: \`./install.sh --target aider\` (or add \`read: CONVENTIONS.md\` to \`.aider.conf.yml\`)" \
    base agent

emit "$OUT/cline/lazyeng.md" "LazyEng" \
    "Cline rules file. Install: \`./install.sh --target cline\`" \
    base agent

# Windsurf requires frontmatter on every rule file.
emit_yaml "$OUT/windsurf/lazyeng.md" \
    "---
trigger: always_on
description: Token-efficient coding rules — library-first, minimal diffs, verify before claiming done.
---" \
    "LazyEng" \
    "Windsurf rule. Install: \`./install.sh --target windsurf\`" \
    base agent

# Cursor ignores .md files in .cursor/rules — it requires the .mdc extension.
emit_yaml "$OUT/cursor/lazyeng.mdc" \
    "---
description: Token-efficient coding rules — library-first, minimal diffs, verify before claiming done.
alwaysApply: true
---" \
    "LazyEng" \
    "Cursor project rule. Install: \`./install.sh --target cursor\`" \
    base agent

# ── Agent Skills: loads on demand, so it can afford the full text ─────────────
emit_yaml "$OUT/skills/lazyeng/SKILL.md" \
    "---
name: lazyeng
description: Token-efficient coding rules. Use when writing, reviewing, or refactoring code — enforces library-first choices, minimal diffs, no filler commentary, and verification before claiming a change works.
license: MIT
compatibility: Any agent that can read files and edit code. No runtime dependencies.
metadata:
  version: \"$VERSION\"
  repository: $REPO
---" \
    "LazyEng" \
    "Agent Skills standard ([agentskills.io](https://agentskills.io)). Install: \`./install.sh --target skill\`" \
    base agent expanded

# ── dist/ map ────────────────────────────────────────────────────────────────
{
    printf '%s\n' "$BANNER"
    printf '\n# dist/ — generated adapters (lazyeng v%s)\n\n' "$VERSION"
    cat <<'MAP'
Every file here is generated from `core/*.md` by `build.sh`. Never edit them by hand.

| File | Install target | Installed to |
|------|----------------|--------------|
| `system-prompt.md` | any chat UI | paste as system prompt |
| `system-prompt-compact.md` | any API | `system` message |
| `AGENTS.md` | Codex, Cursor, Copilot, Gemini CLI, Zed, Amp, opencode | `AGENTS.md` |
| `CLAUDE.md` | Claude Code | `CLAUDE.md` |
| `GEMINI.md` | Gemini CLI | `GEMINI.md` |
| `copilot-instructions.md` | GitHub Copilot | `.github/copilot-instructions.md` |
| `cursor/lazyeng.mdc` | Cursor | `.cursor/rules/lazyeng.mdc` |
| `windsurf/lazyeng.md` | Windsurf | `.windsurf/rules/lazyeng.md` |
| `cline/lazyeng.md` | Cline | `.clinerules/lazyeng.md` |
| `CONVENTIONS.md` | Aider | `CONVENTIONS.md` |
| `skills/lazyeng/SKILL.md` | Agent Skills clients | `.claude/skills/lazyeng/SKILL.md` |

Prefer the installer: `./install.sh --target <name>` — it handles merging into
existing files, `--dry-run`, and `--uninstall`.
MAP
} > "$OUT/README.md"

# ── finish ───────────────────────────────────────────────────────────────────
case $MODE in
    build)
        printf 'built dist/ (lazyeng v%s)\n' "$VERSION"
        ;;
    check)
        if diff -r "$ROOT/dist" "$OUT" >/dev/null 2>&1; then
            printf 'ok: dist/ matches core/\n'
        else
            printf 'ERROR: dist/ is out of date — run ./build.sh\n' >&2
            diff -ru "$ROOT/dist" "$OUT" >&2 || true
            exit 1
        fi
        ;;
    stats)
        printf '%-34s %6s %7s %8s\n' FILE WORDS CHARS '~TOKENS'
        printf '%-34s %6s %7s %8s\n' ---------------------------------- ------ ------- --------
        for f in system-prompt.md system-prompt-compact.md AGENTS.md \
                 skills/lazyeng/SKILL.md; do
            w=$(wc -w < "$ROOT/dist/$f" | tr -d ' ')
            c=$(wc -c < "$ROOT/dist/$f" | tr -d ' ')
            printf '%-34s %6s %7s %8s\n' "$f" "$w" "$c" "$((c / 4))"
        done
        printf '\n~TOKENS = chars/4 heuristic (accurate +/-15%% for English prose).\n'
        ;;
esac
